#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int L, C;
    cin >> L >> C;

    vector<vector<int>> a(L, vector<int>(C));
    for (auto& row : a)
        for (int& x : row)
            cin >> x;

    int cols = C - 1;
    vector<int> height(cols, 0);
    long long answer = 0;

    for (int i = 0; i < L - 1; ++i) {
        for (int j = 0; j < cols; ++j) {
            long long diff = 1LL * a[i][j] + a[i + 1][j + 1]
                           - a[i][j + 1] - a[i + 1][j];
            height[j] = (diff <= 0) ? height[j] + 1 : 0;
        }

        vector<int> st;
        for (int j = 0; j <= cols; ++j) {
            int h = (j == cols ? 0 : height[j]);
            while (!st.empty() && height[st.back()] > h) {
                int bar = st.back();
                st.pop_back();
                int width = st.empty() ? j : j - st.back() - 1;
                if (height[bar] > 0) {
                    answer = max(answer, 1LL * (height[bar] + 1) * (width + 1));
                }
            }
            st.push_back(j);
        }
    }

    cout << answer << '\n';
    return 0;
}
